private ScrollView manualScroll(LinearLayout box){ScrollView scroll=new ScrollView(this);scroll.addView(box);return scroll;} private boolean saveManualNote(DirectStore store,double sys,double dia,double pulse,String note){String id=UUID.randomUUID().toString();String key="note:"+getPackageName()+":"+id;if(!getPreferences(0).edit().putString(key,note).commit())throw new IllegalStateException("Notiz konnte nicht gespeichert werden");try{if(store.saveManual(id,Instant.now(),sys,dia,pulse))return true;}catch(RuntimeException e){getPreferences(0).edit().remove(key).commit();throw e;}getPreferences(0).edit().remove(key).commit();return false;}private void manualMeasurement(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(30,12,30,8);box.addView(text("Messwerte und bei Bedarf eine Notiz eintragen. Datum und Uhrzeit werden automatisch gesetzt.",16));EditText sys=new EditText(this);sys.setHint("SYS, z. B. 135");sys.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);box.addView(sys);EditText dia=new EditText(this);dia.setHint("DIA, z. B. 85");dia.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);box.addView(dia);EditText pulse=new EditText(this);pulse.setHint("Puls, z. B. 68");pulse.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);box.addView(pulse);EditText note=new EditText(this);note.setHint("Notiz (optional)");note.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);note.setMinLines(2);box.addView(note);android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(this).setTitle("Messung bearbeiten · Werte per Hand eintragen") .setView(manualScroll(box)).setNegativeButton("Abbrechen",null).setPositiveButton("Speichern",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{double s=Double.parseDouble(sys.getText().toString().trim().replace(',','.')),d=Double.parseDouble(dia.getText().toString().trim().replace(',','.')),p=Double.parseDouble(pulse.getText().toString().trim().replace(',','.'));if(s<50||s>300||d<30||d>200||p<30||p>250||s<=d)throw new IllegalArgumentException();try(DirectStore store=new DirectStore(this)){if(!saveManualNote(store,s,d,p,note.getText().toString()))throw new IllegalStateException();}dialog.dismiss();savedScroll=0;show();Toast.makeText(this,"Handmessung gespeichert.",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Bitte gültige Werte für SYS, DIA und Puls eingeben.",Toast.LENGTH_LONG).show();}}));dialog.show();}
private LinearLayout buildExportPage(){LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(8,18,8,36);TextView heading=text("Daten senden an …",24);heading.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);page.addView(heading);page.addView(text("Wähle, wohin deine Messwerte gehen sollen.",16));Button printer=new Button(this);printer.setText("Drucker");styleMainButton(printer,Color.rgb(70,95,125));printer.setOnClickListener(v->exportOptions(3,false));page.addView(printer);Button pcFile=new Button(this);pcFile.setText("PC-Datei speichern (z. B. per USB)");styleMainButton(pcFile,Color.rgb(20,135,145));pcFile.setOnClickListener(v->pcFileMenu());page.addView(pcFile);Button pcShare=new Button(this);pcShare.setText("PC-Datei senden an …");styleMainButton(pcShare,Color.rgb(25,112,220));pcShare.setOnClickListener(v->pcFileMenu(true));page.addView(pcShare);page.addView(text("USB ist nur zum direkten Kopieren nötig. Mit Senden an wählst du eine App für die Übergabe; danach die Datei am PC importieren.",14));Button doctor=new Button(this);doctor.setText("Arzt");styleMainButton(doctor,Color.rgb(25,145,70));doctor.setOnClickListener(v->exportOptions(1,true));page.addView(doctor);return page;}private void exportFromPage(int mode,int range,int formatId){if(start==null||end==null||records.isEmpty()){Toast.makeText(this,"Bitte zuerst Messwerte laden.",Toast.LENGTH_LONG).show();switchPage(0);return;}LocalDate to=end.atZone(ZoneId.systemDefault()).toLocalDate();int days=range+1;LocalDate from=to.minusDays(days-1);LocalDate loaded=start.atZone(ZoneId.systemDefault()).toLocalDate();if(from.isBefore(loaded))from=loaded;String ext=new String[]{"pdf","xlsx","csv"}[Math.max(0,Math.min(2,formatId-810))];exportPdf(mode,ext,from,to,false,"");}
private void applyBrightness(int value){android.view.WindowManager.LayoutParams params=getWindow().getAttributes();params.screenBrightness=Math.max(0.05f,Math.min(1f,(value+5)/100f));getWindow().setAttributes(params);}
private void rememberExport(String ext,LocalDate from,LocalDate to){String value=ext.toUpperCase(Locale.GERMANY)+" · "+LocalDateTime.now().format(DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm"))+"\n"+from.format(DateTimeFormatter.ofPattern("dd.MM.yyyy"))+" bis "+to.format(DateTimeFormatter.ofPattern("dd.MM.yyyy"));getSharedPreferences("exportUi",0).edit().putString("last",value).apply();if(lastExport!=null)lastExport.setText(value);}
