private void selectionPanel(){if(selectionBox==null)return;selectionBox.removeAllViews();Set<String> available=new HashSet<>();for(BloodPressureRecord r:records)if(!hidden.contains(recordKey(r))&&UserProfile.owns(this,recordKey(r)))available.add(recordKey(r));selected.retainAll(available);CheckBox all=new CheckBox(this);all.setText("Alle markieren · "+selected.size()+" ausgewählt");all.setChecked(!available.isEmpty()&&selected.containsAll(available));all.setEnabled(!loading&&!available.isEmpty());all.setOnCheckedChangeListener((b,on)->{selected.clear();if(on)selected.addAll(available);savedScroll=mainScroll.getScrollY();show();});selectionBox.addView(all);if(selected.isEmpty())return;Button actions=new Button(this);actions.setText("Auswahl bearbeiten ("+selected.size()+")");styleMainButton(actions,Color.rgb(21,83,170));actions.setOnClickListener(v->selectionActions());selectionBox.addView(actions);Button cancel=new Button(this);cancel.setText("Auswahl aufheben");cancel.setOnClickListener(v->{selected.clear();savedScroll=mainScroll.getScrollY();show();});selectionBox.addView(cancel);}
