private String matchingPulse(BloodPressureRecord r){if(directPulse.containsKey(recordKey(r))){double value=directPulse.get(recordKey(r));return Double.isFinite(value)?String.format(Locale.GERMANY,"Puls %.0f bpm",value):"Puls —";}Long found=null;for(PulseValue v:pulses){if(v.source.equals(r.getMetadata().getDataOrigin().getPackageName())&&v.time.equals(r.getTime())){if(found!=null&&found.longValue()!=v.bpm)return "Puls — (nicht eindeutig)";found=v.bpm;}}return found==null?"Puls —":"Puls "+found+" bpm";}
