private String dayGroupLabel(LocalDate date){LocalDate today=LocalDate.now();if(date.equals(today))return "Heute";if(date.equals(today.minusDays(1)))return "Gestern";return date.format(DateTimeFormatter.ofPattern("dd. MMM yyyy",Locale.GERMANY));}private void mergeDirect(){
records.removeIf(r->r.getMetadata().getDataOrigin().getPackageName().equals(getPackageName()));directPulse.clear();estimatedTimes.clear();irregular.clear();
try(DirectStore store=new DirectStore(this)){for(DirectStore.Entry e:store.read()){
if(start!=null&&e.time.isBefore(start)&&!getPreferences(0).getStringSet("restoredKeys",Collections.emptySet()).contains(getPackageName()+":"+e.id))continue;
android.health.connect.datatypes.Metadata meta=new android.health.connect.datatypes.Metadata.Builder().setId(e.id).setDataOrigin(new android.health.connect.datatypes.DataOrigin.Builder().setPackageName(getPackageName()).build()).build();
BloodPressureRecord local;
try{local=new BloodPressureRecord.Builder(meta,e.time,0,android.health.connect.datatypes.units.Pressure.fromMillimetersOfMercury(e.sys),android.health.connect.datatypes.units.Pressure.fromMillimetersOfMercury(e.dia),0).build();}catch(IllegalArgumentException invalid){continue;}
// Prefer the durable direct copy only for an exact matching measurement.
records.removeIf(r->!e.estimated&&r.getMetadata().getDataOrigin().getPackageName().equals("com.omronhealthcare.omronconnect")&&r.getTime().getEpochSecond()==e.time.getEpochSecond()&&Math.abs(r.getSystolic().getInMillimetersOfMercury()-e.sys)<0.01&&Math.abs(r.getDiastolic().getInMillimetersOfMercury()-e.dia)<0.01&&!getPreferences(0).contains("note:"+recordKey(r))&&!hidden.contains(recordKey(r)));
if(e.status!=null&&(e.status&4)!=0)irregular.add(recordKey(local));records.add(local);directPulse.put(recordKey(local),e.pulse);if(e.estimated)estimatedTimes.add(recordKey(local));
}}catch(Exception e){Toast.makeText(this,"Gespeicherte Bluetooth-Werte konnten nicht geladen werden.",Toast.LENGTH_LONG).show();}
}
