private int pressureBand(double sys,double dia){boolean esh=getSharedPreferences("pressureScale",0).getString("guideline","ESC2024").equals("ESH2023");return sys>=140||dia>=90?3:esh?(sys>=130||dia>=85?2:1):(sys>=120||dia>=70?2:1);}private String noteFor(BloodPressureRecord r){return getPreferences(0).getString("note:"+recordKey(r),"");}
