for(int n=0;n<2;n++){final int index=n;Button date=new Button(this);date.setText((n==0?"Von: ":"Bis: ")+dates[n].format(DateTimeFormatter.ofPattern("dd.MM.yyyy")));box.addView(date);date.setOnClickListener(v->{LocalDate d=dates[index];android.app.DatePickerDialog picker=new android.app.DatePickerDialog(this,(view,y,m,day)->{dates[index]=LocalDate.of(y,m+1,day);date.setText((index==0?"Von: ":"Bis: ")+dates[index].format(DateTimeFormatter.ofPattern("dd.MM.yyyy")));},d.getYear(),d.getMonthValue()-1,d.getDayOfMonth());picker.getDatePicker().setMinDate(start.toEpochMilli());picker.getDatePicker().setMaxDate(end.toEpochMilli());picker.show();});}
box.addView(text("Format",18));RadioGroup formats=new RadioGroup(this);String[] labels={"PDF","Excel (.xlsx)","CSV"};for(int i=0;i<3;i++){RadioButton radio=new RadioButton(this);radio.setId(100+i);radio.setText(labels[i]);formats.addView(radio);}formats.check(100);box.addView(formats);
box.addView(text("Aktion",18));RadioGroup actions=new RadioGroup(this);RadioButton save=new RadioButton(this);save.setId(202);save.setText("Als Datei speichern");actions.addView(save);RadioButton send=new RadioButton(this);send.setId(201);send.setText("Teilen (WhatsApp, E-Mail …)");actions.addView(send);RadioButton print=new RadioButton(this);print.setId(203);print.setText("An Drucker senden");if(report)print.setEnabled(false);actions.addView(print);actions.setOnCheckedChangeListener((group,id)->{boolean printing=id==203;if(printing)formats.check(100);for(int i=0;i<formats.getChildCount();i++)formats.getChildAt(i).setEnabled(!printing);});actions.check(200+initialMode);box.addView(actions);
android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(this).setTitle(report?"Arztbericht":"Blutdruck exportieren").setView(scroll).setNegativeButton("Abbrechen",null).setPositiveButton("Export",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{if(dates[0].isAfter(dates[1])){Toast.makeText(this,"Das Von-Datum muss vor dem Bis-Datum liegen.",Toast.LENGTH_LONG).show();return;}String ext=new String[]{"pdf","xlsx","csv"}[formats.getCheckedRadioButtonId()-100];dialog.dismiss();exportPdf(actions.getCheckedRadioButtonId()-200,ext,dates[0],dates[1],report,patient.getText().toString().trim());}));dialog.show();
