private void exportPdf(int mode,String ext,LocalDate from,LocalDate to,boolean report,String patient){exportPdf(mode,ext,from,to,report,patient,null,false);}
private void exportPdf(int mode,String ext,LocalDate from,LocalDate to,boolean report,String patient,Set<String> only,boolean cut){
if(loading||visibleCount()==0){Toast.makeText(this,"Bitte zuerst die Werte vollständig laden.",Toast.LENGTH_LONG).show();return;}
ArrayList<String[]> rows=new ArrayList<>();Set<String> exportedKeys=new HashSet<>();
DateTimeFormatter fmt=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm:ss",Locale.GERMANY).withZone(ZoneId.systemDefault());
for(BloodPressureRecord r:records){if((only!=null&&!only.contains(recordKey(r)))||hidden.contains(recordKey(r))||!UserProfile.owns(this,recordKey(r))||r.getTime().atZone(ZoneId.systemDefault()).toLocalDate().isBefore(from)||r.getTime().atZone(ZoneId.systemDefault()).toLocalDate().isAfter(to))continue;exportedKeys.add(recordKey(r));String pulse=matchingPulse(r);String value=pulse.endsWith(" bpm")?pulse.substring(5,pulse.length()-4):"—";rows.add(new String[]{fmt.format(r.getTime()),String.format(Locale.GERMANY,"%.0f / %.0f",r.getSystolic().getInMillimetersOfMercury(),r.getDiastolic().getInMillimetersOfMercury()),value,dayPart(r),(estimatedTimes.contains(recordKey(r))?"Empfangszeit; Gerätezeit nicht verfügbar. ":"")+(irregular.contains(recordKey(r))?"Unregelmäßiger Herzschlag (Gerätemeldung). ":"")+noteFor(r)});}
if(rows.isEmpty()){Toast.makeText(this,"Keine Messungen im gewählten Zeitraum.",Toast.LENGTH_LONG).show();return;}String period="Zeitraum: "+from.format(DateTimeFormatter.ofPattern("dd.MM.yyyy"))+" bis "+to.format(DateTimeFormatter.ofPattern("dd.MM.yyyy"));

if(mode==3){try{PdfExport.open(this,rows,period,pulseMessage,UserProfile.reportLine(this,""));}catch(Exception e){new android.app.AlertDialog.Builder(this).setTitle("Drucken nicht möglich").setMessage("Druckdialog konnte nicht geöffnet werden.\n"+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage())).setPositiveButton("OK",null).show();}return;}
try{java.io.File file=new java.io.File(getCacheDir(),UUID.randomUUID().toString()+"."+ext);String reportProfile=UserProfile.reportLine(this,patient);if(report&&ext.equals("pdf"))PdfExport.saveReport(file,rows,period,pulseMessage,reportProfile);else if(report)TableExport.saveReport(file,rows,ext.equals("xlsx"),period,reportProfile);else if(ext.equals("pdf"))PdfExport.save(file,rows,period,pulseMessage,UserProfile.reportLine(this,""));else TableExport.save(file,rows,ext.equals("xlsx"),UserProfile.reportLine(this,""));rememberExport(ext,from,to);
if(mode==1){android.net.Uri uri=android.net.Uri.parse("content://"+getPackageName()+".pdf/"+file.getName());Intent send=new Intent(Intent.ACTION_SEND).setType(TableExport.mime(ext)).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(android.content.ClipData.newRawUri("Blutdruckliste",uri));startActivity(Intent.createChooser(send,"Datei senden an"));}
else{pendingCut.clear();if(cut)pendingCut.addAll(exportedKeys);pendingPdf=file;Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(TableExport.mime(ext)).putExtra(Intent.EXTRA_TITLE,(report?"Arztbericht.":"Blutdruckliste.")+ext);startActivityForResult(save,72);}
}catch(Exception e){pendingCut.clear();Toast.makeText(this,"Datei konnte nicht bereitgestellt werden.",Toast.LENGTH_LONG).show();}
}
@Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putStringArrayList("selected",new ArrayList<>(selected));state.putStringArrayList("pendingCut",new ArrayList<>(pendingCut));if(pendingPdf!=null)state.putString("pendingPdf",pendingPdf.getName());}
@Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(licenseBlocked())return;if(request==73){if(result==RESULT_OK&&data!=null&&data.getData()!=null)restoreFile(data);else{restoring=false;recreate();}return;}if(request!=72)return;boolean saved=false;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&pendingPdf!=null){try(java.io.InputStream in=new java.io.FileInputStream(pendingPdf);java.io.OutputStream out=getContentResolver().openOutputStream(data.getData(),"w")){if(out==null)throw new java.io.IOException();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);out.flush();}catch(Exception e){Toast.makeText(this,"Datei konnte nicht gespeichert werden. Messungen bleiben erhalten.",Toast.LENGTH_LONG).show();pendingPdf=null;pendingCut.clear();return;}saved=true;Toast.makeText(this,"Datei gespeichert",Toast.LENGTH_LONG).show();}if(saved&&!pendingCut.isEmpty())hideSelection(new HashSet<>(pendingCut));pendingCut.clear();pendingPdf=null;}
@Override protected void onResume(){super.onResume();if(AppLock.ensure(this))return;if(restoring)return;MedicalNotice.show(this,true);if(licenseBlocked())return;valuesView=true;showMeasurementMode();switchPage(0);savedScroll=0;UpdateChecker.check(this,false);visible=true;if(android.bluetooth.BluetoothAdapter.checkBluetoothAddress(getSharedPreferences("bluetooth",0).getString("device",""))&&!getSharedPreferences("bluetooth",0).getBoolean("noticeAsked",false)){getSharedPreferences("bluetooth",0).edit().putBoolean("noticeAsked",true).apply();if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},84);}if(bluetoothReceiver==null)bluetoothReceiver=new MainBluetoothReceiver(this,()->{if(!visible)return;if(loading||getCurrentFocus() instanceof EditText){pendingDirect=true;return;}savedScroll=mainScroll.getScrollY();show();});if(!MeasurementService.ensure(this))bluetoothReceiver.start();else bluetoothReceiver.stop();if(!measurementRegistered){if(android.os.Build.VERSION.SDK_INT>=33)registerReceiver(measurementEvents,new android.content.IntentFilter(getPackageName()+".MEASUREMENT"),android.content.Context.RECEIVER_NOT_EXPORTED);else registerReceiver(measurementEvents,new android.content.IntentFilter(getPackageName()+".MEASUREMENT"));measurementRegistered=true;}refreshHandler.removeCallbacks(refreshTick);refreshHandler.removeCallbacks(pcPollTick);refreshHandler.postDelayed(refreshTick,60000);if(android.os.Build.VERSION.SDK_INT>=34&&checkSelfPermission(READ)==PackageManager.PERMISSION_GRANTED){if(!loading)load();}else{records.clear();pulses.clear();list.removeAllViews();end=Instant.now();start=end.minus(Duration.ofDays(31));show();status.setVisibility(View.VISIBLE);status.append(android.os.Build.VERSION.SDK_INT<34?"Android 10 bis 13: gespeicherte, manuelle und Bluetooth-Werte werden angezeigt.":"Health-Connect-Lesefreigabe fehlt; gespeicherte Bluetooth-Werte werden angezeigt.");}}
@Override protected void onPause(){persistNotes();if(measurementRegistered){unregisterReceiver(measurementEvents);measurementRegistered=false;}if(bluetoothReceiver!=null)bluetoothReceiver.stop();visible=false;refreshHandler.removeCallbacks(refreshTick);refreshHandler.removeCallbacks(pcPollTick);super.onPause();}

private android.app.AlertDialog pcDialog;private boolean pcSyncOnOpen=false,pcSyncManualAfterLoad=false;

private void pcSettings(){if(!featureAccess(false))return;LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(30,16,30,16);box.addView(text("Am PC im Tagebuch auf Handy koppeln klicken. QR-Code scannen oder den Code einfügen. Die Kopplung bleibt gespeichert. Neue Werte werden übertragen, wenn du im PC-Tagebuch auf Aktualisieren tippst. Puls 180 muss dabei geöffnet sein, beide Geräte müssen im selben Heimnetz sein. Ein neuer QR-Scan ist normalerweise nicht nötig. Löschen bleibt je Gerät getrennt.",16));Button scan=new Button(this);scan.setText("QR-Code scannen");styleMainButton(scan,Color.rgb(21,83,170));box.addView(scan);scan.setOnClickListener(v->{if(pcDialog!=null)pcDialog.dismiss();startActivity(new Intent(this,QrScanActivity.class));});EditText code=new EditText(this);code.setHint("Kopplungscode (alternativ)");code.setInputType(1|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);box.addView(code);box.addView(text(getSharedPreferences("pcSync",0).getString("status","Noch nicht gekoppelt"),15));pcDialog=new android.app.AlertDialog.Builder(this).setTitle("PC-Synchronisierung").setView(box).setPositiveButton("Verbinden",(d,w)->{try{if(code.getText().length()>0)getSharedPreferences("pcSync",0).edit().putString("code",PcSync.validate(code.getText().toString())).commit();pcSyncOnOpen=true;if(!loading){pcSyncOnOpen=false;syncPc();}}catch(Exception e){Toast.makeText(this,"Bitte den vollständigen Kopplungscode einfügen.",1).show();}}).setNeutralButton("Trennen",(d,w)->{getSharedPreferences("pcSync",0).edit().remove("code").putString("status","Getrennt").commit();}).setNegativeButton("Schließen",null).show();}
private void syncPc(){syncPc(null,false,false);}private void syncPcRequested(){syncPc(null,false,true);}private void syncPc(Set<String> only,boolean manual){syncPc(only,manual,false);}private void syncPc(Set<String> only,boolean manual,boolean requestedOnly){if(!License.allowed(this)){if(manual)featureAccess(false);return;}if(loading||!visible){if(manual)Toast.makeText(this,"Bitte warten, bis die Messungen geladen sind.",0).show();return;}if(getSharedPreferences("pcSync",0).getString("code","").isEmpty()){if(manual)Toast.makeText(this,"PC-Tagebuch noch nicht gekoppelt. Bitte im Menü PC-Synchronisierung öffnen.",1).show();return;}try{org.json.JSONArray rows=new org.json.JSONArray();for(BloodPressureRecord r:records){String key=recordKey(r);if(hidden.contains(key)||!UserProfile.owns(this,key)||(only!=null&&!only.contains(key)))continue;String id=getSharedPreferences("pcSync",0).getBoolean("pc:"+r.getMetadata().getId(),false)?r.getMetadata().getId():UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();String p=matchingPulse(r);Object pulse=org.json.JSONObject.NULL;if(p.endsWith(" bpm"))try{pulse=(int)Math.round(Double.parseDouble(p.substring(5,p.length()-4).replace(',','.')));}catch(Exception ignored){}String n=noteFor(r);if(estimatedTimes.contains(key))n="Empfangszeit; Gerätezeit nicht verfügbar. "+n;if(irregular.contains(key))n="Unregelmäßiger Herzschlag (Gerätemeldung). "+n;rows.put(new org.json.JSONObject().put("id",id).put("systolic",(int)Math.round(r.getSystolic().getInMillimetersOfMercury())).put("diastolic",(int)Math.round(r.getDiastolic().getInMillimetersOfMercury())).put("pulse",pulse).put("measuredAt",r.getTime().toString()).put("note",n));}if(rows.length()==0&&only!=null){if(manual)Toast.makeText(this,"Die ausgewählte Messung ist nicht mehr verfügbar.",1).show();return;}PcSync.Result result=(changed,message)->{if(isDestroyed()||isFinishing())return;if(manual)Toast.makeText(this,message,Toast.LENGTH_LONG).show();if(changed&&visible){if(getCurrentFocus() instanceof EditText||loading)pendingDirect=true;else show();}};if(requestedOnly)PcSync.poll(this,rows,result);else PcSync.run(this,rows,result);}catch(Exception e){getSharedPreferences("pcSync",0).edit().putString("status","Abgleich konnte nicht vorbereitet werden.").apply();if(manual)Toast.makeText(this,"Abgleich konnte nicht vorbereitet werden.",1).show();}}

private void pcFileMenu(){pcFileMenu(false);}private void pcFileMenu(boolean share){new android.app.AlertDialog.Builder(this).setTitle(share?"PC-Datei senden an …":"PC-Datei speichern").setItems(new String[]{"Alle Werte dieser Person","Markierte Werte ("+selected.size()+")"},(d,w)->exportPcFile(w==0?null:new HashSet<>(selected),share)).setNegativeButton("Abbrechen",null).show();}
private void exportPcFile(Set<String> only){exportPcFile(only,false);}private void exportPcFile(Set<String> only,boolean share){
 if(!featureAccess(false))return;
 if(loading){Toast.makeText(this,"Bitte warten, bis die Werte geladen sind.",1).show();return;}
 if(only!=null&&only.isEmpty()){Toast.makeText(this,"Bitte zuerst Werte markieren.",Toast.LENGTH_LONG).show();switchPage(0);return;}
 pendingCut.clear();
 try{
  org.json.JSONArray rows=new org.json.JSONArray();
  if(!captureArchive())return;
  try(DiaryArchive archive=new DiaryArchive(this)){
   org.json.JSONArray stored=archive.rows(null);
   for(int i=0;i<stored.length();i++){
    org.json.JSONObject r=stored.getJSONObject(i);String key=r.getString("key");
    if((only!=null&&!only.contains(key))||hidden.contains(key)||!UserProfile.belongs(this,key))continue;
    String id=UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();
    Object pulse=org.json.JSONObject.NULL;
    java.util.regex.Matcher m=java.util.regex.Pattern.compile("Puls\\s+([0-9]+(?:[.,][0-9]+)?)").matcher(r.optString("pulseText"));
    if(m.find())try{pulse=(int)Math.round(Double.parseDouble(m.group(1).replace(',','.')));}catch(Exception ignored){}
    String note=getPreferences(0).getString("note:"+key,r.optString("note"));
    if(r.optBoolean("estimated"))note="Empfangszeit; Gerätezeit nicht verfügbar. "+note;
    if(r.optBoolean("irregular"))note="Unregelmäßiger Herzschlag (Gerätemeldung). "+note;
    rows.put(new org.json.JSONObject().put("id",id).put("systolic",(int)Math.round(r.getDouble("systolic"))).put("diastolic",(int)Math.round(r.getDouble("diastolic"))).put("pulse",pulse).put("measuredAt",r.getString("time")).put("note",note));
   }
  }
  if(rows.length()==0){Toast.makeText(this,"Keine passenden Werte verfügbar.",1).show();return;}
  org.json.JSONObject data=new org.json.JSONObject().put("format","puls180-pc-transfer").put("version",1).put("profileName",UserProfile.activeLabel(this)).put("profileData",UserProfile.transferData(this)).put("readings",rows);
  byte[] bytes=data.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
  if(bytes.length>1900000)throw new java.io.IOException("Zu viele Werte");
  java.io.File output=new java.io.File(getCacheDir(),UUID.randomUUID()+".json");
  try(java.io.FileOutputStream stream=new java.io.FileOutputStream(output)){stream.write(bytes);}
  if(share){sharePcFile(output);}else{pendingPdf=output;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"Puls-180-PC-Werte-"+LocalDate.now()+".json"),72);}
 }catch(Exception e){pendingPdf=null;Toast.makeText(this,"PC-Datei konnte nicht erstellt werden. Werte bleiben erhalten.",Toast.LENGTH_LONG).show();}
}
private void sharePcFile(java.io.File file){android.net.Uri uri=android.net.Uri.parse("content://"+getPackageName()+".pdf/"+file.getName());Intent send=new Intent(Intent.ACTION_SEND).setType("application/json").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(android.content.ClipData.newRawUri("Puls-180-PC-Werte.json",uri));startActivity(Intent.createChooser(send,"PC-Datei senden an …"));}
private void savePcDiary(){if(!featureAccess(false))return;pendingCut.clear();try{int id=getResources().getIdentifier("pc_tagebuch","raw",getPackageName());if(id==0)throw new java.io.IOException();java.io.File file=new java.io.File(getCacheDir(),UUID.randomUUID().toString()+".zip");try(java.io.InputStream in=getResources().openRawResource(id);java.io.OutputStream out=new java.io.FileOutputStream(file)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}pendingPdf=file;Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"Puls-180-PC-Tagebuch-5.12.zip");startActivityForResult(save,72);Toast.makeText(this,"ZIP speichern, auf den PC übertragen und dort vollständig entpacken. Dann Start-Web-App.cmd öffnen.",Toast.LENGTH_LONG).show();}catch(Exception e){pendingPdf=null;Toast.makeText(this,"PC-Tagebuch konnte nicht bereitgestellt werden.",Toast.LENGTH_LONG).show();}}
private final Map<EditText,String> noteEditors=new HashMap<>();
private boolean persistNote(EditText editor,String key,boolean notify){String value=editor.getText().toString();if(value.equals(getPreferences(0).getString("note:"+key,"")))return true;boolean ok=getPreferences(0).edit().putString("note:"+key,value).commit();if(notify||!ok)Toast.makeText(this,ok?"Gespeichert ✓":"Speichern fehlgeschlagen – bitte erneut versuchen",Toast.LENGTH_SHORT).show();return ok;}
private boolean persistNotes(){boolean ok=true;for(Map.Entry<EditText,String> e:noteEditors.entrySet())if(!persistNote(e.getKey(),e.getValue(),false))ok=false;return ok;}
private org.json.JSONObject snapshot(BloodPressureRecord r)throws Exception {String key=recordKey(r);return new org.json.JSONObject().put("key",key).put("time",r.getTime().toString()).put("month",YearMonth.from(r.getTime().atZone(ZoneId.systemDefault())).toString()).put("systolic",r.getSystolic().getInMillimetersOfMercury()).put("diastolic",r.getDiastolic().getInMillimetersOfMercury()).put("pulseText",matchingPulse(r)).put("dayPart",dayPart(r)).put("estimated",estimatedTimes.contains(key)).put("irregular",irregular.contains(key)).put("note",noteFor(r));}
private boolean captureArchive(){try{org.json.JSONArray rows=new org.json.JSONArray();for(BloodPressureRecord r:records)rows.put(snapshot(r));try(DiaryArchive a=new DiaryArchive(this)){a.capture(rows);}return true;}catch(Exception e){Toast.makeText(this,"Monatsablage konnte nicht gespeichert werden.",1).show();return false;}}
private void showMeasurementDetails(org.json.JSONObject row){double sys=row.optDouble("systolic"),dia=row.optDouble("diastolic"),pp=sys-dia,map=dia+pp/3.0;boolean esh=getSharedPreferences("pressureScale",0).getString("guideline","ESC2024").equals("ESH2023");LinearLayout box=new LinearLayout(this);box.setOrientation(1);int pad=(int)(18*getResources().getDisplayMetrics().density);box.setPadding(pad,8,pad,pad);TextView values=text(String.format(Locale.GERMANY,"Blutdruck  %.0f / %.0f mmHg\n%s\n\nMittlerer arterieller Druck  %.0f mmHg\nPulsdruck  %.0f mmHg\nUnregelmäßiger Puls  %s",sys,dia,row.optString("pulseText","Puls —"),map,pp,row.optBoolean("irregular")?"Gemeldet (vom Gerät)":"Nicht gemeldet"),18);box.addView(values);box.addView(new PressureScaleView(this,sys,dia,esh),new LinearLayout.LayoutParams(-1,(int)(280*getResources().getDisplayMetrics().density)));box.addView(text("Mittlerer arterieller Druck und Pulsdruck werden aus SYS und DIA berechnet. Die Skala und einzelne Werte sind keine Diagnose.",13));ScrollView scroll=new ScrollView(this);scroll.addView(box);new android.app.AlertDialog.Builder(this).setTitle("Messwert-Details").setView(scroll).setPositiveButton("Schließen",null).show();}private void measurementActions(org.json.JSONObject row){if(restoring||loading||!persistNotes())return;new android.app.AlertDialog.Builder(this).setTitle("Messung bearbeiten").setItems(new String[]{"Daten versenden an …","Kopieren oder speichern","Als PC-Datei speichern","Als PC-Datei senden an …","Werte per Hand eintragen","Löschen"},(d,which)->{if(which==5){new android.app.AlertDialog.Builder(this).setTitle("Messung löschen?").setMessage("Aus der App und Monatsablage ausblenden. Im Menü wiederherstellbar; Health Connect bleibt unverändert.").setPositiveButton("Löschen",(x,w)->hideSelection(Collections.singleton(row.optString("key")))).setNegativeButton("Abbrechen",null).show();}else if(which==4)manualValues();else if(which==3)exportPcFile(Collections.singleton(row.optString("key")),true);else if(which==2)exportPcFile(Collections.singleton(row.optString("key")));else if(which==1)measurementDestination(row,false);else sendMeasurement(row);}).setNegativeButton("Abbrechen",null).show();}private void sendMeasurement(org.json.JSONObject row){new android.app.AlertDialog.Builder(this).setTitle("Format zum Versenden").setItems(new String[]{"PDF","Excel","CSV"},(d,w)->exportSnapshot(row,new String[]{"pdf","xlsx","csv"}[w],true,false)).setNegativeButton("Abbrechen",null).show();}
private void manualValues(){if(restoring||loading||!persistNotes())return;LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(28,16,28,8);int numeric=android.text.InputType.TYPE_CLASS_NUMBER;EditText sys=new EditText(this);sys.setHint("Systolisch (mmHg)");sys.setInputType(numeric);box.addView(sys);EditText dia=new EditText(this);dia.setHint("Diastolisch (mmHg)");dia.setInputType(numeric);box.addView(dia);EditText pulse=new EditText(this);pulse.setHint("Puls (optional)");pulse.setInputType(numeric);box.addView(pulse);EditText note=new EditText(this);note.setHint("Notiz (optional)");note.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);note.setMinLines(2);box.addView(note);box.addView(text("Datum, Uhrzeit und Tageszeit werden automatisch gesetzt.",14));android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(this).setTitle("Werte per Hand eintragen") .setView(manualScroll(box)).setNegativeButton("Abbrechen",null).setPositiveButton("Speichern",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{ManualValues values=ManualValues.parse(sys.getText().toString(),dia.getText().toString(),pulse.getText().toString());try(DirectStore store=new DirectStore(this)){if(!saveManualNote(store,values.systolic,values.diastolic,values.pulse,note.getText().toString()))throw new IllegalStateException();}savedScroll=0;dialog.dismiss();show();Toast.makeText(this,"Handwerte gespeichert.",Toast.LENGTH_SHORT).show();}catch(IllegalArgumentException e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Handwerte konnten nicht gespeichert werden.",Toast.LENGTH_LONG).show();}}));dialog.show();}
private void measurementDestination(org.json.JSONObject row,boolean move){new android.app.AlertDialog.Builder(this).setTitle(move?"Verschieben nach …":"Kopieren nach …").setItems(move?new String[]{"Monatsordner","Als Datei speichern"}:new String[]{"Monatsordner","Als Datei speichern","Datei versenden"},(d,which)->{if(which==0)chooseMonth(row,move);else new android.app.AlertDialog.Builder(this).setTitle("Format wählen").setItems(new String[]{"PDF","Excel","CSV"},(x,f)->exportSnapshot(row,new String[]{"pdf","xlsx","csv"}[f],which==2,move)).setNegativeButton("Abbrechen",null).show();}).setNegativeButton("Abbrechen",null).show();}
