private void exportMonthRows(String ext,boolean report,boolean print){try{org.json.JSONArray data=selectedMonthRows();if(data.length()==0){Toast.makeText(this,"In der Auswahl sind keine Messungen.",1).show();return;}ArrayList<String[]> rows=new ArrayList<>();DateTimeFormatter fmt=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm:ss").withZone(ZoneId.systemDefault());for(int i=0;i<data.length();i++){org.json.JSONObject row=data.getJSONObject(i);String pulse=row.optString("pulseText"),value=pulse.endsWith(" bpm")?pulse.substring(5,pulse.length()-4):"—";rows.add(new String[]{fmt.format(Instant.parse(row.getString("time"))),Math.round(row.getDouble("systolic"))+" / "+Math.round(row.getDouble("diastolic")),value,row.optString("dayPart"),row.optString("note")});}String period=selectedMonths.size()+" ausgewählte Monatsordner";if(print){PdfExport.open(this,rows,period,"",UserProfile.reportLine(this,""));return;}java.io.File file=new java.io.File(getCacheDir(),UUID.randomUUID()+"."+ext);if(report&&ext.equals("pdf"))PdfExport.saveReport(file,rows,period,"",UserProfile.reportLine(this,""));else if(report)TableExport.saveReport(file,rows,ext.equals("xlsx"),period,UserProfile.reportLine(this,""));else if(ext.equals("pdf"))PdfExport.save(file,rows,period,"",UserProfile.reportLine(this,""));else TableExport.save(file,rows,ext.equals("xlsx"),UserProfile.reportLine(this,""));android.net.Uri uri=android.net.Uri.parse("content://"+getPackageName()+".pdf/"+file.getName());Intent send=new Intent(Intent.ACTION_SEND).setType(TableExport.mime(ext)).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(android.content.ClipData.newRawUri(report?"Arztbericht":"Monatsordner",uri));startActivity(Intent.createChooser(send,report?"Arztbericht senden an":"Monatsordner versenden an"));}catch(Exception e){Toast.makeText(this,print?"Drucken nicht möglich.":"Monatsordner konnten nicht bereitgestellt werden.",1).show();}}
