private void deleteSelectedMonths(){new android.app.AlertDialog.Builder(this).setTitle("Monatsablage löschen?").setMessage("Die ausgewählten Monatsordner werden aus der App-Ablage entfernt. Originalwerte in Health Connect bleiben erhalten.").setPositiveButton("Löschen",(d,w)->{try(DiaryArchive archive=new DiaryArchive(this)){archive.removeMonths(new HashSet<>(selectedMonths));selectedMonths.clear();renderMonthOverview();Toast.makeText(this,"Monatsablage gelöscht",0).show();}catch(Exception e){Toast.makeText(this,"Löschen fehlgeschlagen.",1).show();}}).setNegativeButton("Abbrechen",null).show();}private void showYearOverview(){if(!persistNotes()||!captureArchive())return;final int year=LocalDate.now().getYear();String[] monthNames={"Januar","Februar","März","April","Mai","Juni","Juli","August","September","Oktober","November","Dezember"};String[] labels=new String[12];try(DiaryArchive archive=new DiaryArchive(this)){for(int m=1;m<=12;m++){org.json.JSONArray data=archive.rows(YearMonth.of(year,m).toString());int count=0;double sys=0,dia=0,pulse=0;int pc=0;for(int i=0;i<data.length();i++){org.json.JSONObject row=data.getJSONObject(i);String key=row.getString("key");if(hidden.contains(key)||!UserProfile.belongs(this,key))continue;count++;sys+=row.optDouble("systolic");dia+=row.optDouble("diastolic");java.util.regex.Matcher match=java.util.regex.Pattern.compile("Puls\\s+([0-9]+(?:[.,][0-9]+)?)").matcher(row.optString("pulseText"));if(match.find()){pulse+=Double.parseDouble(match.group(1).replace(',','.'));pc++;}}labels[m-1]=monthNames[m-1]+" · "+count+" Messungen"+(count>0?"\nDurchschnitt "+Math.round(sys/count)+" / "+Math.round(dia/count)+" mmHg"+(pc>0?" · Puls "+Math.round(pulse/pc):""):"\nNoch keine Messungen");}}catch(Exception e){Toast.makeText(this,"Monatsübersicht konnte nicht geladen werden.",1).show();return;}new android.app.AlertDialog.Builder(this).setTitle("Monatsordner · "+UserProfile.activeLabel(this)+" · "+year).setItems(labels,(d,w)->openMonth(YearMonth.of(year,w+1).toString())).setNegativeButton("Schließen",null).show();}private void showMonths(){if(!persistNotes()||!captureArchive())return;LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(28,12,28,12);NumberPicker year=new NumberPicker(this);year.setMinValue(1970);year.setMaxValue(2200);year.setValue(LocalDate.now().getYear());box.addView(year);Spinner months=new Spinner(this);months.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Januar","Februar","März","April","Mai","Juni","Juli","August","September","Oktober","November","Dezember"}));months.setSelection(LocalDate.now().getMonthValue()-1);box.addView(months);new android.app.AlertDialog.Builder(this).setTitle("Monatsordner").setView(box).setPositiveButton("Öffnen",(d,w)->openMonth(YearMonth.of(year.getValue(),months.getSelectedItemPosition()+1).toString())).setNegativeButton("Schließen",null).show();}
private void openMonth(String month){try(DiaryArchive archive=new DiaryArchive(this)){org.json.JSONArray data=archive.rows(month);ArrayList<org.json.JSONObject> entries=new ArrayList<>();for(int i=0;i<data.length();i++)if(!hidden.contains(data.getJSONObject(i).getString("key"))&&UserProfile.belongs(this,data.getJSONObject(i).getString("key")))entries.add(data.getJSONObject(i));entries.sort((a,b)->b.optString("time").compareTo(a.optString("time")));String[] labels=new String[entries.size()];DateTimeFormatter fmt=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm").withZone(ZoneId.systemDefault());for(int i=0;i<labels.length;i++){org.json.JSONObject row=entries.get(i);labels[i]=fmt.format(Instant.parse(row.getString("time")))+" · "+Math.round(row.getDouble("systolic"))+" / "+Math.round(row.getDouble("diastolic"))+" mmHg\n"+row.optString("pulseText");}android.app.AlertDialog.Builder dialog=new android.app.AlertDialog.Builder(this).setTitle("Monatsordner "+month).setNegativeButton("Schließen",null);if(labels.length==0)dialog.setMessage("Keine Messungen abgelegt.");else dialog.setItems(labels,(d,w)->measurementActions(entries.get(w)));dialog.show();}catch(Exception e){Toast.makeText(this,"Monatsordner konnte nicht geöffnet werden.",1).show();}}
private void exportSnapshot(org.json.JSONObject row,String ext,boolean share,boolean move){if(!persistNotes())return;pendingCut.clear();try{String key=row.getString("key");if(hidden.contains(key))throw new IllegalStateException();Instant time=Instant.parse(row.getString("time"));String pulse=row.optString("pulseText"),value=pulse.endsWith(" bpm")?pulse.substring(5,pulse.length()-4):"—";String note=getPreferences(0).getString("note:"+key,row.optString("note"));ArrayList<String[]> rows=new ArrayList<>();rows.add(new String[]{DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm:ss").withZone(ZoneId.systemDefault()).format(time),Math.round(row.getDouble("systolic"))+" / "+Math.round(row.getDouble("diastolic")),value,row.optString("dayPart"),(row.optBoolean("estimated")?"Empfangszeit. ":"")+(row.optBoolean("irregular")?"Unregelmäßiger Herzschlag (Gerätemeldung). ":"")+note});java.io.File file=new java.io.File(getCacheDir(),UUID.randomUUID()+"."+ext);if(ext.equals("pdf"))PdfExport.save(file,rows,"Einzelmessung","",UserProfile.reportLine(this,""));else TableExport.save(file,rows,ext.equals("xlsx"),UserProfile.reportLine(this,""));if(share){android.net.Uri uri=android.net.Uri.parse("content://"+getPackageName()+".pdf/"+file.getName());Intent send=new Intent(Intent.ACTION_SEND).setType(TableExport.mime(ext)).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(android.content.ClipData.newRawUri("Messung",uri));startActivity(Intent.createChooser(send,"Datei senden an"));}else{pendingPdf=file;if(move)pendingCut.add(key);startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(TableExport.mime(ext)).putExtra(Intent.EXTRA_TITLE,"Blutdruck-Messung."+ext),72);}}catch(Exception e){pendingCut.clear();pendingPdf=null;Toast.makeText(this,"Export fehlgeschlagen. Messung bleibt erhalten.",1).show();}}
private void backup(){if(!featureAccess(false))return;if(loading){Toast.makeText(this,"Bitte warten, bis alle Werte geladen sind.",0).show();return;}if(!persistNotes()||!captureArchive())return;pendingCut.clear();try{org.json.JSONObject data=new org.json.JSONObject().put("format","schaepi-blutdruck-backup").put("version",2).put("settings",AppBackup.settings(this)).put("createdAt",Instant.now().toString()).put("app",getPackageName());try(DiaryArchive archive=new DiaryArchive(this)){data.put("measurements",archive.rows(null)).put("folders",archive.links());}org.json.JSONObject notes=new org.json.JSONObject();for(Map.Entry<String,?> entry:getPreferences(0).getAll().entrySet())if(entry.getKey().startsWith("note:")&&entry.getValue() instanceof String)notes.put(entry.getKey(),entry.getValue());data.put("notes",notes).put("hidden",new org.json.JSONArray(new ArrayList<>(hidden)));org.json.JSONArray direct=new org.json.JSONArray();try(DirectStore store=new DirectStore(this);android.database.Cursor c=store.getReadableDatabase().rawQuery("SELECT * FROM readings",null)){while(c.moveToNext()){org.json.JSONObject row=new org.json.JSONObject();for(int i=0;i<c.getColumnCount();i++)row.put(c.getColumnName(i),c.isNull(i)?org.json.JSONObject.NULL:c.getString(i));direct.put(row);}}data.put("directReadings",direct);org.json.JSONArray heart=new org.json.JSONArray();for(PulseValue p:pulses)heart.put(new org.json.JSONObject().put("time",p.time.toString()).put("source",p.source).put("bpm",p.bpm));data.put("loadedPulseValues",heart).put("scope","Gespeicherte App-Messungen und bisher geladene Health-Connect-Werte; kein vollständiges Health-Connect-Backup. Keine Lizenz- oder Kopplungsschlüssel.");AppBackup.validate(data,getPackageName());byte[] backupBytes=data.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8);if(backupBytes.length>50*1024*1024)throw new java.io.IOException("Backup zu gross");java.io.File file=new java.io.File(getCacheDir(),UUID.randomUUID()+".json");try(java.io.Writer writer=new java.io.OutputStreamWriter(new java.io.FileOutputStream(file),java.nio.charset.StandardCharsets.UTF_8)){writer.write(data.toString(2));}pendingPdf=file;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"Blutdruck-Backup-"+LocalDate.now()+".json"),72);}catch(Exception e){pendingPdf=null;Toast.makeText(this,"Backup konnte nicht erstellt werden.",1).show();}}


private boolean restoring=false;
private void backupMenu(){if(!featureAccess(false))return;if(loading||restoring){Toast.makeText(this,"Bitte warten, bis der laufende Vorgang fertig ist.",1).show();return;}new android.app.AlertDialog.Builder(this).setTitle("Backup").setItems(new String[]{"Backup erstellen","Backup wiederherstellen","Monatsordner"},(d,w)->{if(w==0)backup();else if(w==2)showMonths();else{if(!persistNotes())return;restoring=true;setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LOCKED);try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json"),73);}catch(Exception e){restoring=false;Toast.makeText(this,"Dateiauswahl konnte nicht geöffnet werden.",1).show();}}}).show();}
private void restoreFile(Intent intent){if(!featureAccess(false))return;restoring=true;setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LOCKED);android.app.ProgressDialog progress=android.app.ProgressDialog.show(this,"Backup prüfen","Sicherungsdatei wird geprüft …",true,false);new Thread(()->{try{final org.json.JSONObject data;try(java.io.InputStream in=getContentResolver().openInputStream(intent.getData())){if(in==null)throw new java.io.IOException();data=AppBackup.read(in,getPackageName());}runOnUiThread(()->{progress.dismiss();new android.app.AlertDialog.Builder(this).setTitle("Backup wiederherstellen?").setMessage(data.optJSONArray("measurements").length()+" gespeicherte Messungen. Fehlende Messungen, Notizen, Monatszuordnungen und Einstellungen werden ergänzt. Vorhandene Daten bleiben erhalten. Freischaltung und PC-Kopplung werden nicht übertragen.").setPositiveButton("Wiederherstellen",(d,w)->applyBackup(data)).setNegativeButton("Abbrechen",(d,w)->{restoring=false;recreate();}).setOnCancelListener(d->{restoring=false;recreate();}).show();});}catch(Exception e){runOnUiThread(()->{progress.dismiss();restoring=false;new android.app.AlertDialog.Builder(this).setTitle("Backup nicht eingelesen").setMessage("Die Datei ist ungültig, zu groß oder gehört zur anderen App-Version (persönlich / Verkauf). Es wurden keine Daten geändert.").setPositiveButton("OK",(d,w)->recreate()).show();});}},"Backup-Pruefung").start();}
private void applyBackup(org.json.JSONObject data){if(!featureAccess(false))return;android.app.ProgressDialog progress=android.app.ProgressDialog.show(this,"Wiederherstellen","App-Daten werden wiederhergestellt …",true,false);new Thread(()->{try{int count=AppBackup.restore(this,data);boolean finished=AppBackup.finish(this);runOnUiThread(()->{progress.dismiss();noteEditors.clear();restoring=false;Toast.makeText(this,finished?"Backup wiederhergestellt: "+count+" fehlende Messungen ergänzt.":"Messungen gespeichert. Einstellungen werden beim nächsten Start fertiggestellt.",1).show();recreate();});}catch(Exception e){runOnUiThread(()->{progress.dismiss();restoring=false;Toast.makeText(this,"Wiederherstellung konnte nicht abgeschlossen werden. Bitte App neu öffnen.",1).show();recreate();});}},"Backup-Restore").start();}
private void mergeArchive(){try(DiaryArchive archive=new DiaryArchive(this)){Set<String> present=new HashSet<>();for(BloodPressureRecord r:records)present.add(recordKey(r));org.json.JSONArray rows=archive.rows(null);for(int i=0;i<rows.length();i++){org.json.JSONObject row=rows.getJSONObject(i);String key=row.getString("key");if(!getPreferences(0).getStringSet("restoredKeys",Collections.emptySet()).contains(key)||present.contains(key))continue;int split=key.indexOf(':');android.health.connect.datatypes.Metadata meta=new android.health.connect.datatypes.Metadata.Builder().setId(key.substring(split+1)).setDataOrigin(new android.health.connect.datatypes.DataOrigin.Builder().setPackageName(key.substring(0,split)).build()).build();BloodPressureRecord r=new BloodPressureRecord.Builder(meta,Instant.parse(row.getString("time")),0,android.health.connect.datatypes.units.Pressure.fromMillimetersOfMercury(row.getDouble("systolic")),android.health.connect.datatypes.units.Pressure.fromMillimetersOfMercury(row.getDouble("diastolic")),0).build();records.add(r);present.add(key);if(row.optBoolean("estimated"))estimatedTimes.add(key);if(row.optBoolean("irregular"))irregular.add(key);java.util.regex.Matcher m=java.util.regex.Pattern.compile("Puls\\s+([0-9]+(?:[.,][0-9]+)?)\\s*bpm").matcher(row.optString("pulseText"));if(m.find())directPulse.put(key,Double.parseDouble(m.group(1).replace(',','.')));}}catch(Exception e){Toast.makeText(this,"Archiv konnte nicht vollständig geladen werden.",1).show();}try{Set<String> seen=new HashSet<>();for(PulseValue p:pulses)seen.add(p.time+"|"+p.source+"|"+p.bpm);org.json.JSONArray a=new org.json.JSONArray(getPreferences(0).getString("restoredPulseValues","[]"));for(int i=0;i<a.length();i++){org.json.JSONObject p=a.getJSONObject(i);Instant t=Instant.parse(p.getString("time"));String s=p.getString("source");long bpm=p.getLong("bpm");if(seen.add(t+"|"+s+"|"+bpm))pulses.add(new PulseValue(t,s,bpm));}}catch(Exception e){Toast.makeText(this,"Gesicherte Pulswerte konnten nicht geladen werden.",1).show();}}
