private void receptionSettings(){android.content.SharedPreferences prefs=getSharedPreferences("bluetooth",0);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(24,16,24,16);Switch bg=new Switch(this);bg.setText("Bluetooth im Hintergrund empfangen");bg.setChecked(prefs.getBoolean("background",true));box.addView(bg);Switch speech=new Switch(this);speech.setText("Neue Messungen automatisch vorlesen");speech.setChecked(prefs.getBoolean("speech",true));box.addView(speech);box.addView(text("Direkter Bluetooth-Empfang vom gespeicherten Gerät, auch außerhalb dieser Ansicht. Android zeigt eine Benachrichtigung. Nach Neustart oder erzwungenem Beenden die App erneut öffnen. Health Connect wird hierdurch nicht im Hintergrund abgefragt. Ansagen sind hörbar für Personen in deiner Nähe und nutzen nur eine deutsche Offline-Stimme.",16));box.addView(text(prefs.getString("speechStatus",""),15));bg.setOnCheckedChangeListener((b,on)->{prefs.edit().putBoolean("background",on).apply();if(on){if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},84);if(bluetoothReceiver!=null)bluetoothReceiver.stop();if(!MeasurementService.ensure(this))Toast.makeText(this,"Bitte zuerst ein Bluetooth-Gerät koppeln und die Freigabe erteilen.",1).show();}else{stopService(new Intent(this,MeasurementService.class));if(bluetoothReceiver!=null)bluetoothReceiver.start();}});speech.setOnCheckedChangeListener((b,on)->{prefs.edit().putBoolean("speech",on).apply();if(!on)MeasurementSpeech.stop();});new android.app.AlertDialog.Builder(this).setTitle("Empfang & Sprachansage").setView(box).setPositiveButton("Schließen",null).show();}
